-- AutoCare Tracker - Supabase schema
-- Each user only sees and changes their own rows (RLS). Ids are generated by
-- the app, so the primary keys are (user_id, id): two users can import the
-- same backup without clashing.

-- ---------- Vehicles ----------
create table public.vehicles (
    user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
    id text not null check (id ~ '^[A-Za-z0-9]{1,40}$'),
    make text not null default '' check (char_length(make) <= 60),
    model text not null default '' check (char_length(model) <= 60),
    year integer check (year between 1900 and 2100),
    plate text not null default '' check (char_length(plate) <= 20),
    mileage integer not null default 0 check (mileage between 0 and 5000000),
    initial_mileage integer check (initial_mileage between 0 and 5000000),
    registration_date date,
    insurance_due date,
    tax_due date,
    color text check (color is null or color ~ '^#[0-9A-Fa-f]{6}$'),
    fuel_type text check (fuel_type is null or fuel_type in ('gasoline', 'diesel', 'hybrid', 'electric')),
    notes text not null default '' check (char_length(notes) <= 1000),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    primary key (user_id, id)
);

-- ---------- Expenses ----------
create table public.expenses (
    user_id uuid not null default auth.uid() references auth.users (id) on delete cascade,
    id text not null check (id ~ '^[A-Za-z0-9]{1,40}$'),
    vehicle_id text not null,
    date date not null,
    category text not null check (category in ('oil', 'tires', 'brakes', 'itv', 'parts', 'maintenance', 'insurance', 'tax', 'fuel', 'other')),
    description text not null default '' check (char_length(description) <= 200),
    cost numeric(10, 2) not null default 0 check (cost between 0 and 1000000),
    mileage integer not null default 0 check (mileage between 0 and 5000000),
    liters numeric(8, 2) check (liters is null or liters > 0),
    price_per_liter numeric(8, 3) check (price_per_liter is null or price_per_liter > 0),
    full_tank boolean,
    shop text not null default '' check (char_length(shop) <= 100),
    notes text not null default '' check (char_length(notes) <= 1000),
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    primary key (user_id, id),
    foreign key (user_id, vehicle_id) references public.vehicles (user_id, id) on delete cascade
);

create index expenses_vehicle_idx on public.expenses (user_id, vehicle_id);
create index expenses_date_idx on public.expenses (user_id, date);

-- ---------- Settings (one row per user) ----------
create table public.user_settings (
    user_id uuid primary key default auth.uid() references auth.users (id) on delete cascade,
    settings jsonb not null default '{}'::jsonb check (pg_column_size(settings) < 8192),
    privacy_accepted_at timestamptz,
    updated_at timestamptz not null default now()
);

-- ---------- updated_at ----------
create function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
    new.updated_at := now();
    return new;
end;
$$;

create trigger vehicles_updated_at before update on public.vehicles
    for each row execute function public.set_updated_at();
create trigger expenses_updated_at before update on public.expenses
    for each row execute function public.set_updated_at();
create trigger user_settings_updated_at before update on public.user_settings
    for each row execute function public.set_updated_at();

-- ---------- Row Level Security ----------
alter table public.vehicles enable row level security;
alter table public.expenses enable row level security;
alter table public.user_settings enable row level security;

create policy "vehicles: own rows select" on public.vehicles for select to authenticated
    using ((select auth.uid()) = user_id);
create policy "vehicles: own rows insert" on public.vehicles for insert to authenticated
    with check ((select auth.uid()) = user_id);
create policy "vehicles: own rows update" on public.vehicles for update to authenticated
    using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "vehicles: own rows delete" on public.vehicles for delete to authenticated
    using ((select auth.uid()) = user_id);

create policy "expenses: own rows select" on public.expenses for select to authenticated
    using ((select auth.uid()) = user_id);
create policy "expenses: own rows insert" on public.expenses for insert to authenticated
    with check ((select auth.uid()) = user_id);
create policy "expenses: own rows update" on public.expenses for update to authenticated
    using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "expenses: own rows delete" on public.expenses for delete to authenticated
    using ((select auth.uid()) = user_id);

create policy "settings: own row select" on public.user_settings for select to authenticated
    using ((select auth.uid()) = user_id);
create policy "settings: own row insert" on public.user_settings for insert to authenticated
    with check ((select auth.uid()) = user_id);
create policy "settings: own row update" on public.user_settings for update to authenticated
    using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "settings: own row delete" on public.user_settings for delete to authenticated
    using ((select auth.uid()) = user_id);

-- Only signed-in users reach the tables (RLS then limits them to their rows)
revoke all on public.vehicles, public.expenses, public.user_settings from anon;
grant select, insert, update, delete on public.vehicles, public.expenses, public.user_settings to authenticated;

-- ---------- Photos (Storage) ----------
-- Private bucket; each user writes only in the folder named after their id:
-- vehicle-photos/<user_id>/<vehicle_id>.jpg
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('vehicle-photos', 'vehicle-photos', false, 2097152, array['image/jpeg', 'image/webp', 'image/png']);

create policy "photos: own folder select" on storage.objects for select to authenticated
    using (bucket_id = 'vehicle-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "photos: own folder insert" on storage.objects for insert to authenticated
    with check (bucket_id = 'vehicle-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "photos: own folder update" on storage.objects for update to authenticated
    using (bucket_id = 'vehicle-photos' and (storage.foldername(name))[1] = (select auth.uid())::text)
    with check (bucket_id = 'vehicle-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "photos: own folder delete" on storage.objects for delete to authenticated
    using (bucket_id = 'vehicle-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
